// POC seed importer.
//
// Loads the committed `apps/api/data/poc-seed.json` (generated by
// scripts/extract-poc-data.mjs from the CorpDigi index.html) and commits the
// ENTIRE dataset — all entities + all relations — into `main` as ONE immutable
// commit via the model engine.
//
// Design notes:
//  - ensureMainBranch() is idempotent; it creates `main` + an empty initial
//    commit if absent, else returns the existing branch id.
//  - We use op 'add' for every entity and relation (this is the first seed).
//  - One commit keeps the seed atomic: either the whole graph lands or none of
//    it does (CommitService.commit runs in a single transaction).
//  - The seed is pre-validated by the extractor (enum conformance + no dangling
//    relations), so this importer trusts the file and does not re-coerce.

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import type { Entity, Relation } from '@archi-graph/shared';
import type { Db } from '../db/client';
import { CommitService, ensureMainBranch } from '../model/commit.service';

export interface PocSeed {
  documents: Entity[];
  relations: Relation[];
}

export interface ImportResult {
  entities: number;
  relations: number;
}

// src/import -> apps/api/data/poc-seed.json. Resolve relative to this module so
// it works under both tsx/vitest (src) and compiled (dist) layouts — the
// relative depth from the source file is the same in both.
const SEED_PATH = resolve(__dirname, '..', '..', 'data', 'poc-seed.json');

/** Reads and parses the committed POC seed file. */
export function loadPocSeed(seedPath: string = SEED_PATH): PocSeed {
  const raw = readFileSync(seedPath, 'utf8');
  const seed = JSON.parse(raw) as PocSeed;
  if (!Array.isArray(seed.documents) || !Array.isArray(seed.relations)) {
    throw new Error(`Malformed POC seed at ${seedPath}`);
  }
  return seed;
}

/**
 * Imports the POC seed into `main` as a single commit.
 * @returns the number of entities and relations committed.
 */
export async function importPocSeed(
  db: Db,
  seedPath: string = SEED_PATH,
): Promise<ImportResult> {
  const seed = loadPocSeed(seedPath);
  const branchId = await ensureMainBranch(db);
  const service = new CommitService(db);

  await service.commit(
    branchId,
    {
      entities: seed.documents.map((entity) => ({ op: 'add' as const, entity })),
      relations: seed.relations.map((relation) => ({
        op: 'add' as const,
        relation,
      })),
    },
    'import POC CorpDigi dataset as main seed',
  );

  return {
    entities: seed.documents.length,
    relations: seed.relations.length,
  };
}
